<script setup lang="ts">
import { useQuery } from '@tanstack/vue-query';
import { computed, reactive, ref, watch } from 'vue';
import type { ConfigurationItemWire, ConfigurationLifecycleRequestWire } from '../../generated/contracts';
import { defineConfiguration, issueConfigurationLease, listConfigurations, transitionConfiguration, updateConfiguration } from '../../api/config';
import { toClinicalIssue } from '../clinical-error';

type Mode = 'workflow' | 'form' | 'rule' | 'scope';
type Row = Record<string, any>;
const props = defineProps<{ mode: Mode }>();
const defs = {
  workflow: ['WORKFLOW', '业务配置 / 流程编排', '流程与状态设计器', '配置节点、分支、角色、时限、升级、退回与补偿，并用合成病例逐步回放。', 'inpatient-consult-v1', '住院跨科会诊闭环流程'],
  form: ['FORM_TEMPLATE', '业务配置 / 文档结构', '表单与病历模板设计器', '设计字段、分组、布局、计算、可见性、签名与术语映射，并保留历史版本。', 'opd-record-v1', '门诊结构化病历模板'],
  rule: ['RULE', '业务配置 / 规则治理', '规则、时限与提示设计器', '按平台硬门、机构规则、提醒与 AI 建议分层，支持冲突分析和历史回放。', 'clinical-safety-rules-v1', '临床安全与时限规则集'],
  scope: ['SCOPE', '业务配置 / 权限模型', '角色、职责与数据范围设计器', '组合组织、科室、患者关系、班次、资源动作、职责分离和临时授权。', 'clinical-scope-v1', '临床角色与数据范围策略'],
} as const;
const def = computed(() => defs[props.mode]);
const leaseQuery = useQuery({ queryKey: ['business-config', 'lease'], queryFn: issueConfigurationLease, retry: false, staleTime: 300000, gcTime: 0 });
const itemsQuery = useQuery({ queryKey: computed(() => ['business-config', def.value[0]]), queryFn: () => listConfigurations(leaseQuery.data.value!, def.value[0]), enabled: () => Boolean(leaseQuery.data.value), retry: false });
const items = computed(() => itemsQuery.data.value ?? []);
const selected = ref<ConfigurationItemWire | null>(null);
const tab = ref<'design' | 'validate' | 'simulate' | 'versions'>('design');
const activeRow = ref(0); const busy = ref(''); const notice = ref('');
const form = reactive({ key: '', name: '' }); const payload = ref<Record<string, any>>({});
const issue = computed(() => (leaseQuery.error.value ?? itemsQuery.error.value) ? toClinicalIssue(leaseQuery.error.value ?? itemsQuery.error.value) : null);
const rows = (key: string): Row[] => Array.isArray(payload.value[key]) ? payload.value[key] : [];

function defaults(mode: Mode): Record<string, any> {
  if (mode === 'workflow') return { schema_version: 2, description: '覆盖申请、接收、意见、签署、审计、终态、退回与超时升级。', nodes: [
    { id: 'start', name: '发起申请', type: 'START', owner: '经治医生', minutes: 15 }, { id: 'receive', name: '科室接收', type: 'TASK', owner: '目标科室', minutes: 30 },
    { id: 'opinion', name: '专家意见', type: 'TASK', owner: '会诊专家', minutes: 120 }, { id: 'sign', name: '数字签署', type: 'SIGN', owner: '会诊专家', minutes: 20, protected: true },
    { id: 'audit', name: '审计留痕', type: 'AUDIT', owner: '系统', minutes: 1, protected: true }, { id: 'complete', name: '完成', type: 'END', owner: '系统', minutes: 1, terminal: true, protected: true },
  ], edges: [
    { from: 'start', to: 'receive', condition: '申请已提交' }, { from: 'receive', to: 'opinion', condition: '科室接收' }, { from: 'opinion', to: 'sign', condition: '意见完成' },
    { from: 'sign', to: 'audit', condition: '签名有效' }, { from: 'audit', to: 'complete', condition: '审计成功' }, { from: 'receive', to: 'start', condition: '资料不全', compensation: true },
  ], protected_nodes: ['sign', 'audit', 'complete'], timeout_policy: '30 分钟提醒，120 分钟升级科主任，240 分钟升级医务处', synthetic_case: { case_id: 'SYN-CONSULT-20260826-01', patient: '赵明远（合成）' } };
  if (mode === 'form') return { schema_version: 2, description: '结构化门诊病历，支持条件、计算、签署、打印和术语映射。', groups: [{ id: 'history', name: '病史采集', columns: 2 }, { id: 'assessment', name: '评估与计划', columns: 2 }], fields: [
    { id: 'chief_complaint', label: '主诉', type: 'TEXTAREA', group: 'history', required: true, terminology: 'SNOMED-CT' }, { id: 'onset_hours', label: '起病时长（小时）', type: 'NUMBER', group: 'history', required: true, unit: 'h' },
    { id: 'pain_score', label: '疼痛评分', type: 'NUMBER', group: 'history', required: true, validation: '0 <= value <= 10' }, { id: 'risk_level', label: '胸痛风险分层', type: 'CALCULATED', group: 'assessment', required: true, protected: true, calculation: 'pain_score >= 7 ? HIGH : MEDIUM' },
    { id: 'diagnosis', label: '诊断', type: 'CODE', group: 'assessment', required: true, protected: true, terminology: 'ICD-10-CN' }, { id: 'signature', label: '医生签名', type: 'SIGNATURE', group: 'assessment', required: true, protected: true },
  ], terminology_mapping: [{ field: 'diagnosis', system: 'ICD-10-CN' }, { field: 'chief_complaint', system: 'SNOMED-CT' }], print_template: 'A4-门诊病历-v2', sample_values: { chief_complaint: '胸痛 2 小时', pain_score: 8, diagnosis: 'I20.0 不稳定型心绞痛' } };
  if (mode === 'rule') return { schema_version: 2, description: '平台硬门、机构规则、提醒和 AI 建议分层治理。', rule_layer: 'MIXED', rules: [
    { id: 'allergy-block', name: '严重过敏处方阻断', layer: 'PLATFORM_HARD', priority: 1000, condition: '严重过敏且成分命中', action: '阻断处方并要求替代药', evidence: '国家药品不良反应监测规范', exception: '禁止例外', enabled: true },
    { id: 'pediatric-dose', name: '儿科体重剂量校验', layer: 'INSTITUTION_HARD', priority: 800, condition: '年龄<14 且已录入体重', action: '超出 mg/kg 范围时阻断', evidence: '院内儿科用药目录 2026.2', exception: '药师与上级医师双签', enabled: true },
    { id: 'consult-timeout', name: '会诊超时升级', layer: 'REMINDER', priority: 500, condition: '会诊等待>=120分钟', action: '提醒科主任并升级任务', evidence: '医疗核心制度', exception: '急救处理中可延后', enabled: true },
    { id: 'ai-summary', name: 'AI 病情摘要建议', layer: 'AI_ADVICE', priority: 100, condition: '资料完整度>=80%', action: '生成带来源的摘要候选', evidence: 'clinical-ai-golden-v1', exception: '仅供人工确认', enabled: true },
  ], conditions: ['过敏命中', '年龄与体重', '会诊等待时长'], actions: ['阻断', '升级', '提醒', '建议'], sample_case: { case_id: 'SYN-RULE-20260826-01', age: 6, weight_kg: 20, allergy: '青霉素严重过敏', order: '阿莫西林克拉维酸钾' } };
  return { schema_version: 2, description: '按角色、科室、患者关系、班次与资源状态计算最终权限。', roles: ['经治医生', '会诊医生', '护士长', '病案管理员'], data_scopes: ['本科患者', '会诊授权患者', '值班期间', '脱敏汇总'], permissions: [
    { role: '经治医生', resource: '病历草稿', action: '读写', scope: '本科患者', effect: 'ALLOW', temporary_hours: 0, sod: '签署人不能批准本人更正' },
    { role: '会诊医生', resource: '病历全文', action: '只读', scope: '会诊授权患者', effect: 'ALLOW', temporary_hours: 4, sod: '禁止导出' },
    { role: '会诊医生', resource: '批量导出', action: '导出', scope: '全部患者', effect: 'DENY', temporary_hours: 0, sod: '保护性拒绝优先' },
    { role: '护士长', resource: '护理记录', action: '审核', scope: '本病区', effect: 'ALLOW', temporary_hours: 0, sod: '作者与审核人分离' },
    { role: '病案管理员', resource: '封存病案', action: '解封', scope: '审批案件', effect: 'ALLOW', temporary_hours: 1, sod: '双人批准且到期撤销' },
  ], separation_of_duties: '作者!=审批人；授权申请人!=批准人；紧急访问须事后复核', temporary_grant_hours: 4, simulation: { role: '会诊医生', resource: '病历全文', action: '读取', expected: 'ALLOW' } };
}
function selectItem(item: ConfigurationItemWire) {
  selected.value = item; form.key = item.config_key; form.name = item.display_name;
  const stored = JSON.parse(JSON.stringify(item.payload)) as Record<string, any>;
  const legacy = Number(stored.schema_version ?? 1) < 2
    || (props.mode === 'workflow' && typeof stored.nodes?.[0] === 'string')
    || (props.mode === 'form' && typeof stored.fields?.[0] === 'string')
    || (props.mode === 'rule' && !Array.isArray(stored.rules))
    || (props.mode === 'scope' && !Array.isArray(stored.permissions));
  payload.value = legacy ? { ...defaults(props.mode), description: stored.description ?? defaults(props.mode).description, migrated_from_schema: stored.schema_version ?? 1 } : stored;
  activeRow.value = 0; notice.value = legacy ? '已将旧版通用字段草稿升级为完整领域模型；保存后写入数据库 Schema v2。' : '';
}
function newDraft() { selected.value = null; form.key = def.value[4]; form.name = def.value[5]; payload.value = defaults(props.mode); tab.value = 'design'; activeRow.value = 0; notice.value = '已载入完整仿真草稿，保存后写入数据库。'; }
watch(items, (value) => { if (!selected.value && value[0]) selectItem(value[0]); else if (!selected.value && !value.length) newDraft(); }, { immediate: true });
watch(() => props.mode, () => { selected.value = null; payload.value = {}; tab.value = 'design'; });

async function save() { const lease = leaseQuery.data.value; if (!lease || busy.value) return; busy.value = 'save'; notice.value = ''; try { const result = selected.value ? await updateConfiguration(lease, selected.value.config_id, { display_name: form.name, payload: payload.value, expected_version: selected.value.row_version }) : await defineConfiguration(lease, { config_type: def.value[0], config_key: form.key, display_name: form.name, payload: payload.value }); await itemsQuery.refetch(); selectItem(result); notice.value = `已保存到数据库 · v${result.row_version}`; } catch (error) { const next = toClinicalIssue(error); notice.value = `${next.code}：${next.message}`; } finally { busy.value = ''; } }
async function lifecycle(action: ConfigurationLifecycleRequestWire['action']) { const lease = leaseQuery.data.value; if (!lease || !selected.value || busy.value) return; busy.value = action; try { const result = await transitionConfiguration(lease, selected.value.config_id, { action, expected_version: selected.value.row_version, reason: action === 'VALIDATE' ? '执行领域静态校验和安全门检查' : '业务配置经评审后推进生命周期' }); selectItem(result); await itemsQuery.refetch(); notice.value = action === 'VALIDATE' ? `静态校验：${result.validation_state === 'VALID' ? '通过' : '发现阻断项'}` : `当前状态：${result.status}`; tab.value = 'validate'; } catch (error) { const next = toClinicalIssue(error); notice.value = `${next.code}：${next.message}`; } finally { busy.value = ''; } }

const validation = computed(() => { const errors: string[] = [], warnings: string[] = []; if (props.mode === 'workflow') { const nodes = rows('nodes'), edges = rows('edges'), ids = nodes.map(n => String(n.id)); if (new Set(ids).size !== ids.length) errors.push('节点 ID 重复。'); if (!nodes.some(n => n.type === 'START')) errors.push('缺少起始节点。'); if (!nodes.some(n => n.terminal || n.type === 'END')) errors.push('流程没有终态。'); edges.forEach(e => { if (!ids.includes(String(e.from)) || !ids.includes(String(e.to))) errors.push(`连线 ${e.from} → ${e.to} 引用不存在节点。`); }); nodes.filter(n => n.type !== 'START' && !n.owner).forEach(n => errors.push(`${n.name} 缺少责任角色。`)); if (!nodes.some(n => n.protected && n.type === 'SIGN')) errors.push('缺少受保护签署节点。'); } else if (props.mode === 'form') { const fields = rows('fields'), ids = fields.map(f => String(f.id)); if (new Set(ids).size !== ids.length) errors.push('字段 ID 重复。'); fields.filter(f => !f.label || !f.group).forEach(f => errors.push(`${f.id || '字段'} 缺少名称或分组。`)); fields.filter(f => f.type === 'CALCULATED' && !f.calculation).forEach(f => errors.push(`${f.label} 缺少计算表达式。`)); warnings.push('已发布或被病历引用的受保护字段只能停用，不能删除。'); } else if (props.mode === 'rule') { rows('rules').filter(r => String(r.layer).includes('HARD') && !r.evidence).forEach(r => errors.push(`${r.name} 是硬规则但缺少证据。`)); rows('rules').filter(r => r.layer === 'AI_ADVICE' && String(r.action).includes('阻断')).forEach(r => errors.push(`${r.name}：AI 建议不能直接阻断。`)); warnings.push('平台硬门优先级最高，机构规则不得降级。'); } else { rows('permissions').filter(p => p.effect === 'ALLOW' && p.scope === '全部患者' && !p.temporary_hours).forEach(p => errors.push(`${p.role} 的 ${p.action} 是无范围高权限。`)); rows('permissions').filter(p => Number(p.temporary_hours) > 24).forEach(p => errors.push(`${p.role} 临时授权超过 24 小时。`)); warnings.push('职责分离与保护性 DENY 不能被临时授权绕过。'); } return { errors, warnings }; });
const simulation = computed(() => { const source = props.mode === 'workflow' ? rows('nodes') : props.mode === 'form' ? rows('fields') : props.mode === 'rule' ? rows('rules') : rows('permissions'); return source.map((r, i) => ({ title: r.name ?? r.label ?? `${r.role} · ${r.resource}`, detail: r.condition ?? r.type ?? `${r.action} / ${r.scope}`, result: props.mode === 'rule' && i === 0 ? '命中 · 阻断' : r.effect ?? (r.terminal ? '到达终态' : '通过') })); });
function add() { const key = props.mode === 'workflow' ? 'nodes' : props.mode === 'form' ? 'fields' : props.mode === 'rule' ? 'rules' : 'permissions'; const list = rows(key); const row = props.mode === 'workflow' ? { id: `review_${list.length + 1}`, name: '人工复核', type: 'TASK', owner: '质控医生', minutes: 60 } : props.mode === 'form' ? { id: `custom_${list.length + 1}`, label: '新字段', type: 'TEXT', group: 'assessment', required: false } : props.mode === 'rule' ? { id: `rule-${list.length + 1}`, name: '新提醒规则', layer: 'REMINDER', priority: 300, condition: '请输入条件', action: '创建待办', evidence: '待补充', exception: '允许关闭', enabled: true } : { role: '经治医生', resource: '临床文档', action: '只读', scope: '本科患者', effect: 'ALLOW', temporary_hours: 0, sod: '无' }; list.push(row); payload.value[key] = [...list]; activeRow.value = list.length - 1; }
function remove(key: string) { const list = rows(key), row = list[activeRow.value]; if (row?.protected) { notice.value = '受保护对象不能删除，只能通过新版本停用。'; return; } list.splice(activeRow.value, 1); payload.value[key] = [...list]; activeRow.value = Math.max(0, activeRow.value - 1); }
const statusLabel = (status: string) => ({ DRAFT: '草稿', PENDING_APPROVAL: '待审批', APPROVED: '已批准', ACTIVE: '已发布', ARCHIVED: '已归档' }[status] ?? status);
</script>

<template>
  <section data-page-root class="content vue-native-page bc-page">
    <div class="page-head"><div class="page-title"><p class="eyebrow">{{ def[1] }}</p><h1>{{ def[2] }}</h1><p>{{ def[3] }}</p></div><div class="head-actions"><button class="btn" @click="tab='versions'">版本与继承</button><button class="btn" :disabled="!selected||Boolean(busy)" @click="lifecycle('VALIDATE')">静态校验</button><button class="btn primary" :disabled="Boolean(busy)" @click="save">{{ busy==='save'?'保存中…':'保存草稿' }}</button></div></div>
    <div v-if="notice" class="bc-notice">{{ notice }}</div><div v-if="issue" class="bc-state error">{{ issue.code }}：{{ issue.message }}</div>
    <div class="bc-shell"><aside class="ledger"><header><div><b>配置台账</b><small>{{ def[0] }} · {{ items.length }} 项</small></div><button title="新建" @click="newDraft">＋</button></header><button v-for="item in items" :key="item.config_id" class="ledger-item" :class="{active:selected?.config_id===item.config_id}" @click="selectItem(item)"><b>{{ item.display_name }}</b><code>{{ item.config_key }}</code><span>{{ statusLabel(item.status) }} · v{{ item.row_version }}</span></button><div v-if="leaseQuery.isPending.value||itemsQuery.isPending.value" class="ledger-loading">正在同步数据库版本…</div><div class="safety"><b>发布安全门</b><p>静态校验、仿真、职责分离、审计和回退证据缺一不可。</p></div></aside>
      <main class="designer"><div class="meta"><label><span>配置名称</span><input v-model="form.name" :disabled="Boolean(selected&&selected.status!=='DRAFT')" /></label><label><span>唯一键</span><input v-model="form.key" :disabled="Boolean(selected)" /></label><em>Schema v{{ payload.schema_version??1 }}</em></div><nav><button :class="{active:tab==='design'}" @click="tab='design'">设计</button><button :class="{active:tab==='validate'}" @click="tab='validate'">校验 <i v-if="validation.errors.length">{{ validation.errors.length }}</i></button><button :class="{active:tab==='simulate'}" @click="tab='simulate'">合成仿真</button><button :class="{active:tab==='versions'}" @click="tab='versions'">版本</button></nav>
        <div v-if="tab==='design'" class="stage">
          <template v-if="mode==='workflow'"><aside class="tools"><b>节点组件</b><button @click="add">＋ 人工任务</button><button @click="add">◇ 条件分支</button><button @click="add">↺ 补偿节点</button><small>签署、审计、终态受保护</small></aside><section class="canvas"><div class="canvas-head"><b>可视化流程画布</b><button @click="tab='simulate'">逐步模拟</button></div><div class="flow"><button v-for="(node,i) in rows('nodes')" :key="node.id" :class="{active:activeRow===i,protected:node.protected,terminal:node.terminal}" @click="activeRow=i"><small>{{ node.type }}</small><b>{{ node.name }}</b><span>{{ node.owner }}</span><em>{{ node.minutes }} 分钟</em></button></div><div class="edges"><b>状态迁移</b><p v-for="(edge,i) in rows('edges')" :key="i"><code>{{ edge.from }}</code><span>到</span><code>{{ edge.to }}</code><em>{{ edge.condition }}</em><i v-if="edge.compensation">退回 / 补偿</i></p></div></section><aside v-if="rows('nodes')[activeRow]" class="properties"><b>节点属性</b><label>名称<input v-model="rows('nodes')[activeRow].name" /></label><label>责任角色<input v-model="rows('nodes')[activeRow].owner" /></label><label>类型<select v-model="rows('nodes')[activeRow].type"><option>START</option><option>TASK</option><option>BRANCH</option><option>SIGN</option><option>AUDIT</option><option>END</option></select></label><label>时限（分钟）<input v-model.number="rows('nodes')[activeRow].minutes" type="number" min="1" /></label><p v-if="rows('nodes')[activeRow].protected" class="protected-note">受保护节点：禁止删除或绕过</p><button class="remove" :disabled="rows('nodes')[activeRow].protected" @click="remove('nodes')">删除节点</button></aside></template>
          <template v-else-if="mode==='form'"><aside class="tools"><b>字段组件</b><button @click="add">T 单行文本</button><button @click="add"># 数值与单位</button><button @click="add">☑ 选项</button><button @click="add">✎ 数字签名</button><small>支持计算、条件和术语映射</small></aside><section class="canvas form-canvas"><div class="canvas-head"><b>A4 表单画布</b><button @click="tab='simulate'">样例填充</button></div><article v-for="group in rows('groups')" :key="group.id"><header><b>{{ group.name }}</b><span>{{ group.columns }} 列</span></header><div><button v-for="field in rows('fields').filter(f=>f.group===group.id)" :key="field.id" :class="{active:activeRow===rows('fields').indexOf(field)}" @click="activeRow=rows('fields').indexOf(field)"><b>{{ field.label }} <i v-if="field.required">*</i></b><span>{{ field.type }}</span><em>{{ field.terminology }}</em></button></div></article></section><aside v-if="rows('fields')[activeRow]" class="properties"><b>字段属性</b><label>字段 ID<input v-model="rows('fields')[activeRow].id" /></label><label>显示名称<input v-model="rows('fields')[activeRow].label" /></label><label>类型<select v-model="rows('fields')[activeRow].type"><option>TEXT</option><option>TEXTAREA</option><option>NUMBER</option><option>CODE</option><option>CALCULATED</option><option>SIGNATURE</option></select></label><label>分组<select v-model="rows('fields')[activeRow].group"><option v-for="group in rows('groups')" :key="group.id" :value="group.id">{{ group.name }}</option></select></label><label>计算 / 校验<textarea v-model="rows('fields')[activeRow].calculation" rows="3" /></label><label class="check"><input v-model="rows('fields')[activeRow].required" type="checkbox" /> 必填</label><p v-if="rows('fields')[activeRow].protected" class="protected-note">受保护或已被历史病历引用</p><button class="remove" :disabled="rows('fields')[activeRow].protected" @click="remove('fields')">删除字段</button></aside></template>
          <template v-else><section class="wide"><header><div><b>{{ mode==='rule'?'规则分层台账':'角色 × 资源 × 动作 × 数据范围' }}</b><small>{{ mode==='rule'?'平台硬门 ＞ 机构硬规则 ＞ 提醒 ＞ AI 建议':'拒绝优先；临时高权必须有到期时间' }}</small></div><button class="btn primary" @click="add">新增{{ mode==='rule'?'规则':'授权' }}</button></header><table><thead><tr v-if="mode==='rule'"><th>规则</th><th>层级/优先级</th><th>条件</th><th>处置</th><th>证据/例外</th></tr><tr v-else><th>角色</th><th>资源</th><th>动作</th><th>范围</th><th>效果</th><th>临时授权</th><th>职责分离</th></tr></thead><tbody><tr v-for="(row,i) in rows(mode==='rule'?'rules':'permissions')" :key="i" :class="{active:activeRow===i}" @click="activeRow=i"><template v-if="mode==='rule'"><td><b>{{ row.name }}</b><code>{{ row.id }}</code></td><td><span class="pill">{{ row.layer }}</span><small>P{{ row.priority }}</small></td><td>{{ row.condition }}</td><td>{{ row.action }}</td><td>{{ row.evidence }}<small>{{ row.exception }}</small></td></template><template v-else><td><b>{{ row.role }}</b></td><td>{{ row.resource }}</td><td>{{ row.action }}</td><td>{{ row.scope }}</td><td><span class="pill" :class="String(row.effect).toLowerCase()">{{ row.effect }}</span></td><td>{{ row.temporary_hours?`${row.temporary_hours} 小时`:'长期' }}</td><td>{{ row.sod }}</td></template></tr></tbody></table><div v-if="mode==='rule'&&rows('rules')[activeRow]" class="inline-editor"><label>自然语言条件<textarea v-model="rows('rules')[activeRow].condition" /></label><label>命中处置<textarea v-model="rows('rules')[activeRow].action" /></label><label>证据<input v-model="rows('rules')[activeRow].evidence" /></label><label>批准例外<input v-model="rows('rules')[activeRow].exception" /></label></div><div v-else-if="rows('permissions')[activeRow]" class="inline-editor scope"><label>角色<input v-model="rows('permissions')[activeRow].role" /></label><label>资源<input v-model="rows('permissions')[activeRow].resource" /></label><label>动作<input v-model="rows('permissions')[activeRow].action" /></label><label>范围<input v-model="rows('permissions')[activeRow].scope" /></label><label>效果<select v-model="rows('permissions')[activeRow].effect"><option>ALLOW</option><option>DENY</option></select></label><label>临时小时<input v-model.number="rows('permissions')[activeRow].temporary_hours" type="number" min="0" max="24" /></label></div></section></template>
        </div>
        <div v-else-if="tab==='validate'" class="results"><header :class="validation.errors.length?'blocked':'passed'"><b>{{ validation.errors.length?'发布已阻断':'静态校验通过' }}</b><p>{{ validation.errors.length?`发现 ${validation.errors.length} 个安全门问题。`:'结构、依赖、保护边界和终态检查通过。' }}</p></header><section><h3>阻断项</h3><p v-if="!validation.errors.length" class="ok">未发现阻断项</p><ul><li v-for="e in validation.errors" :key="e">{{ e }}</li></ul></section><section><h3>风险提示</h3><ul><li v-for="w in validation.warnings" :key="w">{{ w }}</li></ul></section><section v-if="selected"><h3>数据库校验</h3><p>{{ selected.validation_state }} · v{{ selected.row_version }}</p><ul><li v-for="e in selected.validation_errors" :key="e">{{ e }}</li></ul></section></div>
        <div v-else-if="tab==='simulate'" class="results simulation"><header><div><small>合成案例</small><b>{{ (payload.synthetic_case??payload.sample_case)?.case_id??'SYN-BUSINESS-20260826-01' }}</b><p>仅使用仿真数据，不含真实患者信息。</p></div><button class="btn primary">重新运行</button></header><ol><li v-for="(step,i) in simulation" :key="i"><span>{{ i+1 }}</span><div><b>{{ step.title }}</b><p>{{ step.detail }}</p></div><em :class="{blocked:String(step.result).includes('阻断')||step.result==='DENY'}">{{ step.result }}</em></li></ol></div>
        <div v-else class="results versions"><section><h3>当前版本</h3><b>{{ form.name }}</b><code>{{ form.key }}</code><p>{{ payload.description }}</p></section><section><h3>继承与保护边界</h3><div class="chain"><span>平台安全基线</span><b>继承</b><span>机构业务配置</span><b>覆盖非保护项</b><span>科室生效配置</span></div><p>硬门、签署、审计、已引用字段和保护性拒绝不可被低层覆盖。</p></section><section><h3>生命周期</h3><div class="head-actions"><button class="btn" :disabled="!selected||selected.status!=='DRAFT'" @click="lifecycle('SUBMIT')">提交审批</button><button class="btn" disabled>职责分离批准</button><button class="btn primary" :disabled="!selected||selected.status!=='APPROVED'" @click="lifecycle('PUBLISH')">发布</button><button class="btn danger" :disabled="!selected||selected.status!=='ACTIVE'" @click="lifecycle('ROLLBACK')">回退</button></div></section></div>
      </main></div>
  </section>
</template>

